{"command": "cd /workspace && python3 -c "
import numpy as np, wave
for f in ['/workspace/work/dump1.wav','/workspace/work/test1.wav']:
    w=wave.open(f); n=w.getnframes(); sr=w.getframerate(); ch=w.getnchannels(); sw=w.getsampwidth()
    raw=w.readframes(n)
    print(f,'frames',n,'sr',sr,'ch',ch,'sw',sw,'rawlen',len(raw),'dur',n/sr)
    if sw==1:
        d=np.frombuffer(raw,dtype='u1').astype(float)-128
        print('  peak',abs(d).max(),'first20',d[:20])
    else:
        d=np.frombuffer(raw,dtype='<i2').astype(float)
        print('  peak',abs(d).max(),'first10',d[:10])
""}

